function submit_notify_form(obj){var email=$(obj).siblings('input[name=notify_email]').val();var productid=$(obj).siblings('input[name=productid]').val();var storefrontid=$(obj).siblings('input[name=storefrontid]').val();$.post('ajax_notify_by_email.php',{productid:productid,notify_email:email,current_storefront:storefrontid},function(data){if(data){alert(data.content);$(obj).parent().parent('div').hide();}},'json');return false;}function submit_product_notify_form(obj){var form=$('form[name=notifyform]');var email=$('input[name=notify_email]',form).val();var productid=$('input[name=productid]',form).val();var storefrontid=$('input[name=storefrontid]',form).val();$.post('ajax_notify_by_email.php',{productid:productid,notify_email:email,current_storefront:storefrontid},function(data){if(data){alert(data.content);$(obj).parent().parent().hide();}},'json');return false;}
function cidev_createHttpRequestObject(){var xmlHttp;if(window.XMLHttpRequest){try{xmlHttp=new XMLHttpRequest();}catch(e){xmlHttp=false;}}else if(!xmlHttp&&window.ActiveXObject){try{xmlHttp=new ActiveXObject("Microsoft.XMLHTTP");}catch(e){xmlHttp=false;}}if(!xmlHttp)cidev_Error('XMLHttpRequest','Y');else
    return xmlHttp;}function cidev_Error(error,show_alert){if(show_alert=='Y'){if(error=='XMLHttpRequest')alert('There was an Error creating the XMLHttpRequest object.');else if(error=='no_server')alert('There was a problem accessing the server.');}}function cidev_id$(id){return document.getElementById(id)}function surfMetaRegister(){$.post('/api/analytics?_='+(new Date()).getTime(),{'url':window.location.href,'referer':document.referer?document.referer:''});}document.addEventListener('DOMContentLoaded',function(){setTimeout(surfMetaRegister,500);});
!function(t){var i=t(window);t.fn.visible=function(t,e,o){if(!(this.length<1)){var r=this.length>1?this.eq(0):this,n=r.get(0),f=i.width(),h=i.height(),o=o?o:"both",l=e===!0?n.offsetWidth*n.offsetHeight:!0;if("function"==typeof n.getBoundingClientRect){var g=n.getBoundingClientRect(),u=g.top>=0&&g.top<h,s=g.bottom>0&&g.bottom<=h,c=g.left>=0&&g.left<f,a=g.right>0&&g.right<=f,v=t?u||s:u&&s,b=t?c||a:c&&a;if("both"===o)return l&&v&&b;if("vertical"===o)return l&&v;if("horizontal"===o)return l&&b}else{var d=i.scrollTop(),p=d+h,w=i.scrollLeft(),m=w+f,y=r.offset(),z=y.top,B=z+r.height(),C=y.left,R=C+r.width(),j=t===!0?B:z,q=t===!0?z:B,H=t===!0?R:C,L=t===!0?C:R;if("both"===o)return!!l&&p>=q&&j>=d&&m>=L&&H>=w;if("vertical"===o)return!!l&&p>=q&&j>=d;if("horizontal"===o)return!!l&&m>=L&&H>=w}}}}(jQuery);
function popup_image(type,id,max_x,max_y,title){max_x=parseInt(max_x);max_y=parseInt(max_y);if(!max_x)max_x=160;else
    max_x+=25;if(!max_y)max_y=120;else
    max_y+=25;return window.open(xcart_web_dir+'/popup_image.php?type='+type+'&id='+id+'&title='+title+'&area='+current_area,'images','width='+max_x+',height='+max_y+',toolbar=no,status=no,scrollbars=yes,resizable=yes,menubar=no,location=no,direction=no');}